def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    ERROR_DIV = "#DIV/0!"
    ERROR_CYCLE = "#CYCLE!"
    token_re = re.compile(
        r"\s*(<=|>=|<>|[A-Za-z]+[1-9][0-9]?|[0-9]+|[()+\-*/,:=<>])"
    )

    parsed = {}
    for name, content in cells.items():
        if not content.startswith("="):
            parsed[name] = int(content)
            continue

        source = content[1:]
        tokens = []
        pos = 0
        while pos < len(source):
            match = token_re.match(source, pos)
            if not match:
                raise ValueError("Invalid formula")
            tokens.append(match.group(1))
            pos = match.end()
        tokens.append(None)

        index = 0

        def peek():
            return tokens[index]

        def take():
            nonlocal index
            token = tokens[index]
            index += 1
            return token

        def parse_formula():
            node = parse_term()
            while peek() in ("+", "-"):
                op = take()
                node = ("binary", op, node, parse_term())
            return node

        def parse_term():
            node = parse_unary()
            while peek() in ("*", "/"):
                op = take()
                node = ("binary", op, node, parse_unary())
            return node

        def parse_unary():
            if peek() == "-":
                take()
                return ("neg", parse_unary())
            return parse_atom()

        def parse_atom():
            token = take()
            if token == "(":
                node = parse_formula()
                take()  # )
                return node
            if token is None:
                raise ValueError("Unexpected end of formula")
            if token.isdigit():
                return ("literal", int(token))
            if token[0].isalpha():
                name = token.upper()
                if peek() != "(":
                    return ("cell", name)
                take()
                args = []
                if name == "IF":
                    left = parse_formula()
                    op = take()
                    right = parse_formula()
                    take()  # ,
                    then_node = parse_formula()
                    take()  # ,
                    else_node = parse_formula()
                    take()  # )
                    return ("if", left, op, right, then_node, else_node)

                while True:
                    if (
                        peek() is not None
                        and re.fullmatch(r"[A-Za-z]+[1-9][0-9]?", peek())
                        and index + 1 < len(tokens)
                        and tokens[index + 1] == ":"
                    ):
                        start = take().upper()
                        take()
                        end = take().upper()
                        args.append(("range", start, end))
                    else:
                        args.append(("formula_arg", parse_formula()))
                    if peek() != ",":
                        break
                    take()
                take()  # )
                return ("function", name, args)
            raise ValueError("Invalid atom")

        ast = parse_formula()
        parsed[name] = ast

    values = {}
    state = {}

    def col_row(cell):
        return ord(cell[0]) - ord("A"), int(cell[1:])

    def evaluate_cell(name):
        if name not in parsed:
            return 0
        if state.get(name) == 1:
            return ERROR_CYCLE
        if state.get(name) == 2:
            return values[name]

        state[name] = 1
        content = parsed[name]
        value = content if isinstance(content, int) else evaluate(content)
        values[name] = value
        state[name] = 2
        return value

    def evaluate(node):
        kind = node[0]
        if kind == "literal":
            return node[1]
        if kind == "cell":
            return evaluate_cell(node[1])
        if kind == "neg":
            value = evaluate(node[1])
            return value if isinstance(value, str) else -value
        if kind == "binary":
            op, left_node, right_node = node[1:]
            left = evaluate(left_node)
            if isinstance(left, str):
                return left
            right = evaluate(right_node)
            if isinstance(right, str):
                return right
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return ERROR_DIV
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if kind == "if":
            left = evaluate(node[1])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right
            op = node[2]
            matches = {
                "=": left == right,
                "<>": left != right,
                "<": left < right,
                "<=": left <= right,
                ">": left > right,
                ">=": left >= right,
            }[op]
            return evaluate(node[4] if matches else node[5])
        if kind == "function":
            name, args = node[1], node[2]
            collected = []
            for arg in args:
                if arg[0] == "formula_arg":
                    value = evaluate(arg[1])
                    if isinstance(value, str):
                        return value
                    collected.append(value)
                else:
                    _, start, end = arg
                    c1, r1 = col_row(start)
                    c2, r2 = col_row(end)
                    for row in range(min(r1, r2), max(r1, r2) + 1):
                        for col in range(min(c1, c2), max(c1, c2) + 1):
                            cell = chr(ord("A") + col) + str(row)
                            if cell in parsed:
                                value = evaluate_cell(cell)
                                if isinstance(value, str):
                                    return value
                                collected.append(value)
            if name == "SUM":
                return sum(collected)
            if not collected:
                return 0
            if name == "MIN":
                return min(collected)
            return max(collected)
        raise ValueError("Invalid expression")

    return {name: evaluate_cell(name) for name in cells}
